type EventName = 'click' | 'focus' | 'blur';
type HandlerName = `on${Capitalize<EventName>}`;
// 'onClick' | 'onFocus' | 'onBlur'

type HTTPMethod = 'GET' | 'POST' | 'PUT' | 'DELETE';
type Endpoint = `/api/${HTTPMethod}/${string}`;
// '/api/GET/...' | '/api/POST/...' | etc.

// Extract the event name from a handler
type ExtractEventName<T> = T extends `on${infer Event}` ? Event : never;

type ClickHandler = ExtractEventName<'onClick'>; // 'Click'

// Extract route params
type ExtractParams<T extends string> = T extends `${string}?${infer Params}`
  ? Params
  : never;

type Query = ExtractParams<'/users?id=123'>; // 'id=123'
